SELECT gen_random_uuid()::text, 'formula', '$\lim_{x \to \infty}\frac{P(x)}{Q(x)}$', 'Limits of Rational Functions at Infinity', '$\lim_{x \to \infty}\frac{a_n x^n + \cdots}{b_m x^m + \cdots} = \begin{cases} 0 & n < m \\ \frac{a_n}{b_m} & n = m \\ \pm\infty & n > m \end{cases}$', NULL, 'A rational function at infinity follows its highest powers.', '[{"symbol":"$a_n, b_m$","meaning":"leading coefficients"},{"symbol":"$n, m$","meaning":"degrees of the top and bottom"}]'::jsonb, 'Equal degrees give the ratio of leading coefficients: that is the horizontal asymptote.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Calculus 1' AND t."subject" = 'Mathematics' AND s."normKey" = 'limits and continuity' AND s."active"), 'At infinity', true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Calculus 1' AND t."subject" = 'Mathematics'
