SELECT gen_random_uuid()::text, 'formula', '$\lim f^{\,g}$', 'Limit of the 1-to-Infinity Form', '$f \to 1,\ g \to \infty:\quad \lim f^{\,g} = e^{\lim g\,(f - 1)}$', NULL, 'A base tending to 1 raised to a growing power: the exponent of e decides.', '[{"symbol":"$f, g$","meaning":"the base and the exponent"}]'::jsonb, '$\lim_{x \to \infty}\left(1 + \frac3x\right)^{2x} = e^{6}$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Calculus 1' AND t."subject" = 'Mathematics' AND s."normKey" = 'l''hôpital''s rule' AND s."active"), NULL, true, 'PENDING', now(), now()
